    			p.gain = 1;
    			p.exclusiveClass = 0;
    			p.pan = 64;
    			p.reverbGain = DEFAULT_DRUM_REVERB[i] / 127;
    			p.chorusGain = this.channelSystem === "xg" ? DEFAULT_DRUM_REVERB[i] / 127 : 0;
